// LoanReferralServiceHandler is an implementation of the edify.loans.v1.LoanReferralService
// service.
type LoanReferralServiceHandler interface {
	// Totals, breakdowns and processing measures for the filtered applications.
	GetLoanDashboard(context.Context, *connect.Request[v1.GetLoanDashboardRequest]) (*connect.Response[v1.GetLoanDashboardResponse], error)
	ListLoanApplications(context.Context, *connect.Request[v1.ListLoanApplicationsRequest]) (*connect.Response[v1.ListLoanApplicationsResponse], error)
	// One application: its details, timeline, follow-ups and delivery attempts.
	GetLoanApplication(context.Context, *connect.Request[v1.GetLoanApplicationRequest]) (*connect.Response[v1.GetLoanApplicationResponse], error)
	// BTO: a follow-up with the lender. It never changes the application's status.
	RecordFollowUp(context.Context, *connect.Request[v1.RecordFollowUpRequest]) (*connect.Response[v1.RecordFollowUpResponse], error)
	// Country Director or RVP: an oversight note.
	RecordOversightNote(context.Context, *connect.Request[v1.RecordOversightNoteRequest]) (*connect.Response[v1.RecordOversightNoteResponse], error)
	// BTO: take responsibility for an application, or move its next follow-up.
	UpdateTracking(context.Context, *connect.Request[v1.UpdateTrackingRequest]) (*connect.Response[v1.UpdateTrackingResponse], error)
	// BTO: directory schools a submission might be.
	SearchSchools(context.Context, *connect.Request[v1.SearchSchoolsRequest]) (*connect.Response[v1.SearchSchoolsResponse], error)
	// BTO: link a submission to its directory school, or find it is not there.
	ResolveSchoolMatch(context.Context, *connect.Request[v1.ResolveSchoolMatchRequest]) (*connect.Response[v1.ResolveSchoolMatchResponse], error)
	// BTO: queue the lender's notification again (after an address is corrected).
	ResendToLender(context.Context, *connect.Request[v1.ResendToLenderRequest]) (*connect.Response[v1.ResendToLenderResponse], error)
	// BTO: record the lender's decision with its evidence, or withdraw or close.
	RecordCorrection(context.Context, *connect.Request[v1.RecordCorrectionRequest]) (*connect.Response[v1.RecordCorrectionResponse], error)
	// BTO: link the application to the loan its lender registered in the loan ledger.
	LinkRegisteredLoan(context.Context, *connect.Request[v1.LinkRegisteredLoanRequest]) (*connect.Response[v1.LinkRegisteredLoanResponse], error)
	// The universal application link to share with schools.
	GetApplicationLink(context.Context, *connect.Request[v1.GetApplicationLinkRequest]) (*connect.Response[v1.GetApplicationLinkResponse], error)
	// BTO: a link that names one directory school.
	CreateInvitation(context.Context, *connect.Request[v1.CreateInvitationRequest]) (*connect.Response[v1.CreateInvitationResponse], error)
	// The filtered applications as CSV, with the same fields the caller may see.
	ExportLoanApplications(context.Context, *connect.Request[v1.ExportLoanApplicationsRequest]) (*connect.Response[v1.ExportLoanApplicationsResponse], error)
	// A directory school's loan applications and the loans registered for it.
	GetSchoolLoanHistory(context.Context, *connect.Request[v1.GetSchoolLoanHistoryRequest]) (*connect.Response[v1.GetSchoolLoanHistoryResponse], error)
	// Country Director: the Loan Partners and how each receives referrals.
	ListLenderChannels(context.Context, *connect.Request[v1.ListLenderChannelsRequest]) (*connect.Response[v1.ListLenderChannelsResponse], error)
	SaveLenderChannel(context.Context, *connect.Request[v1.SaveLenderChannelRequest]) (*connect.Response[v1.SaveLenderChannelResponse], error)
	// Country Director: email the lender the link that confirms its address.
	SendChannelConfirmation(context.Context, *connect.Request[v1.SendChannelConfirmationRequest]) (*connect.Response[v1.SendChannelConfirmationResponse], error)
	// A lender's own staff (MfiPartnerAdmin, MfiLoanOfficer): their referrals.
	ListMyReferrals(context.Context, *connect.Request[v1.ListMyReferralsRequest]) (*connect.Response[v1.ListMyReferralsResponse], error)
	GetMyReferral(context.Context, *connect.Request[v1.GetMyReferralRequest]) (*connect.Response[v1.GetMyReferralResponse], error)
	RecordLenderUpdate(context.Context, *connect.Request[v1.RecordLenderUpdateRequest]) (*connect.Response[v1.RecordLenderUpdateResponse], error)
}

